-- Add practical workflow guides based on the current FKT interface.
insert into public.fkt_support_faq
  (module, category, question, answer, is_published, sort_order, reviewed_at)
select v.module, v.category, v.question, v.answer, true, v.sort_order, now()
from (values
  ('core','Pesquisa','Como utilizo a pesquisa transversal do FKT?','Na barra superior da aplicação, escolha «Pesquisar». Também pode abrir a pesquisa com Ctrl+K (Windows/Linux) ou Command+K (Mac). Escreva pelo menos dois caracteres. Pode filtrar por módulo, tipo de registo, espaço de trabalho, obra, intervalo de datas e estado. Seleccione um resultado para abrir o registo.',360),
  ('core','Pesquisa','A pesquisa encontra texto dentro dos ficheiros PDF e documentos?','Não. A pesquisa transversal procura texto nos registos e nos respectivos metadados acessíveis. O conteúdo binário dos ficheiros, incluindo o texto interno de PDFs e documentos Office, ainda não está indexado.',370),
  ('core','Conta','Como termino a sessão no FKT?','Abra o menu lateral da aplicação. Na parte inferior, junto à informação da conta, escolha «Sair». A sessão será terminada e regressará ao ecrã público.',380),
  ('core','Ajuda e Suporte','Quem pode criar ou alterar perguntas frequentes?','A gestão das FAQ está reservada ao Administrador Global. Os utilizadores e os administradores dos espaços de trabalho podem consultar as respostas publicadas, mas não podem criar, editar, ordenar, publicar ou retirar FAQ.',390),

  ('works','Diário','Como registo uma entrada no Diário da obra?','Abra «FKT Works» > «Obras» e seleccione a obra. No cabeçalho do detalhe, escolha «Registar no diário». Indique a data e preencha «O que aconteceu hoje?». Estes dois campos são obrigatórios. Em «Informação complementar» pode acrescentar técnico/responsável, meteorologia, equipas, equipamentos, materiais, condicionantes, atrasos e notas. Termine em «Guardar registo».',400),
  ('works','Ocorrências','Como registo uma ocorrência numa obra?','Abra «FKT Works» > «Obras» e seleccione a obra. No cabeçalho, escolha «Nova ocorrência». Descreva o que encontrou; pode tirar uma fotografia ou escolher uma imagem, acrescentar legenda, localização, tipo e especialidade. Registe factos observados, sem antecipar conclusões, e guarde a ocorrência.',410),
  ('works','Ações','Como crio uma ação para acompanhar um problema?','Abra a obra e escolha «Nova ação», no cabeçalho. Descreva a acção e, se aplicável, indique responsável, prazo e prioridade. Pode associá-la à visita de origem e a uma ocorrência. Termine em «Guardar acção». A disponibilidade de criação depende da sua permissão de escrita.',420),
  ('works','Planeamento','Como acrescento uma actividade ao planeamento da obra?','Abra «FKT Works» > «Obras», seleccione a obra e entre em «Planeamento». Escolha «Nova actividade». Indique o título e, se necessário, descrição, datas previstas, duração, responsável/equipa, tarefa ou ocorrência associada e dependências. Pode também registar datas reais e motivo de desvio. Termine em «Guardar actividade».',430),
  ('works','Documentos','Como arquivo um documento na obra?','Abra a obra e entre em «Documentos». Escolha «Arquivar documento». Preencha o título e seleccione o ficheiro. Pode indicar categoria, origem, número/código, data, notas e associar o documento a uma visita ou ocorrência. Os formatos aceites incluem PDF, Office, TXT, JPG e PNG; o limite é 25 MB. Termine em «Guardar documento».',440),
  ('works','Documentos','Como acrescento uma nova versão de um documento?','Abra a obra e entre em «Documentos». Localize o documento e escolha «Nova versão». Seleccione o ficheiro actualizado. A nova versão fica associada ao mesmo documento, preservando o histórico de versões. O limite de tamanho e os formatos permitidos são os mesmos do carregamento inicial.',450),
  ('works','Trabalho offline','Como sincronizo os registos feitos sem Internet?','No FKT Works, consulte o painel de estado de sincronização apresentado abaixo da barra superior. Quando existirem operações pendentes e houver ligação à Internet, escolha «Sincronizar agora». Se existir um conflito, abra-o e compare as versões; pode manter a versão do servidor ou a versão local. Não feche a aplicação antes de confirmar que a fila ficou sincronizada.',460),

  ('lex','Documentos','Como junto um documento a um processo?','Abra «FKT Lex» > «Processos», seleccione o processo e entre em «Documentos». Escolha «Carregar documento». Seleccione o ficheiro e indique, se necessário, nome, categoria, data do documento e notas. O documento fica associado ao processo.',470),
  ('lex','Relatórios','Como guardo o relatório FIRAC em PDF?','Abra «FKT Lex» > «Processos» e seleccione o processo. No cabeçalho, escolha «Relatório PDF». Na página do relatório, escolha «Imprimir / Guardar PDF». Na janela de impressão do dispositivo, seleccione «Guardar como PDF» ou a opção equivalente.',480),

  ('vet','Ficha do animal','Como arquivo ou restauro um animal?','Abra «FKT Vet» > «Canil» e seleccione o animal. Na ficha, use o botão «Arquivar» para retirar o animal da lista activa, preservando o registo. Para um animal arquivado, o mesmo botão passa a «Restaurar». Confirme a operação quando a aplicação o solicitar. É necessária permissão de escrita.',490),
  ('vet','Limitações','Porque não encontro a opção para criar um animal ou uma reserva?','Na interface actual, o ecrã «Canil» não apresenta um botão visível para criar animais e o menu não apresenta uma entrada para «Nova reserva». Embora existam ecrãs internos para estas operações, não há um percurso de navegação normal exposto ao utilizador. Esta limitação tem de ser corrigida na interface; não tente contorná-la através de endereços internos.',500),

  ('dev','Limitações','Porque não encontro a opção para criar um projecto?','O ecrã principal do FKT Dev apresenta projectos activos e ADRs recentes, mas actualmente não mostra um botão visível para criar um projecto. Existe um ecrã de criação no código, mas não está ligado ao percurso normal da interface. A navegação tem de ser corrigida antes de podermos indicar um procedimento ao utilizador.',510),
  ('dev','Contribuidores','Posso gerir os contribuidores de um projecto?','O detalhe de um projecto tem o separador «Contribuidores», mas a própria interface indica «Gestão de contribuidores em breve». A gestão ainda não está disponível nesta versão.',520)
) as v(module, category, question, answer, sort_order)
where not exists (
  select 1 from public.fkt_support_faq existing
  where existing.module = v.module and existing.question = v.question
);
